import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEMS = new Set([
  'con', 'prn', 'aux', 'nul',
  'com1', 'com2', 'com3', 'com4', 'com5', 'com6', 'com7', 'com8', 'com9',
  'lpt1', 'lpt2', 'lpt3', 'lpt4', 'lpt5', 'lpt6', 'lpt7', 'lpt8', 'lpt9',
]);
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isPlainObject(value) {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasExactKeys(value, keys) {
  const own = Reflect.ownKeys(value);
  return own.length === keys.length && own.every(key => keys.includes(key));
}

// Returns the path segments, or null if the path is not a portable relative path.
function splitPortable(relative) {
  if (typeof relative !== 'string' || relative.length === 0) return null;
  const segments = relative.split('/');
  for (const segment of segments) {
    if (!SEGMENT.test(segment)) return null;
    if (DEVICE_STEMS.has(segment.split('.')[0])) return null;
  }
  return segments;
}

// Copies the untrusted manifest into a validated snapshot so later reads cannot change.
function parseManifest(manifest) {
  const invalid = message => fail('ERR_INVALID_MANIFEST', message);
