import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEMS = new Set([
  'con', 'prn', 'aux', 'nul',
  'com1', 'com2', 'com3', 'com4', 'com5', 'com6', 'com7', 'com8', 'com9',
  'lpt1', 'lpt2', 'lpt3', 'lpt4', 'lpt5', 'lpt6', 'lpt7', 'lpt8', 'lpt9',
]);
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isPlainObject(value) {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasExactKeys(value, keys) {
  const own = Reflect.ownKeys(value);
  return own.length === keys.length && own.every(key => keys.includes(key));
}

// Returns the path segments, or null if the path is not a portable relative path.
function splitPortable(relative) {
  if (typeof relative !== 'string' || relative.length === 0) return null;
  const segments = relative.split('/');
  for (const segment of segments) {
    if (!SEGMENT.test(segment)) return null;
    if (DEVICE_STEMS.has(segment.split('.')[0])) return null;
  }
  return segments;
}

// Copies the untrusted manifest into a validated snapshot so later reads cannot change.
function parseManifest(manifest) {
  const invalid = message => fail('ERR_INVALID_MANIFEST', message);
  if (!isPlainObject(manifest) || !hasExactKeys(manifest, ['writes', 'deletes'])) {
    throw invalid('Manifest must contain exactly writes and deletes');
  }
  const rawWrites = manifest.writes;
  const rawDeletes = manifest.deletes;
  if (!Array.isArray(rawWrites) || !Array.isArray(rawDeletes)) {
    throw invalid('Manifest writes and deletes must be arrays');
  }

  const writes = [];
  for (let i = 0; i < rawWrites.length; i++) {
    const item = rawWrites[i];
    if (!isPlainObject(item) || !hasExactKeys(item, ['path', 'content'])) {
      throw invalid(`Write ${i} must contain exactly path and content`);
    }
    const { path: relative, content } = item;
    if (typeof relative !== 'string' || typeof content !== 'string') {
      throw invalid(`Write ${i} path and content must be strings`);
    }
    writes.push({ path: relative, content });
  }

  const deletes = [];
  for (let i = 0; i < rawDeletes.length; i++) {
    const relative = rawDeletes[i];
    if (typeof relative !== 'string') throw invalid(`Delete ${i} must be a path string`);
    deletes.push(relative);
  }

  const targets = [
    ...writes.map(item => ({ path: item.path, operation: 'write' })),
    ...deletes.map(relative => ({ path: relative, operation: 'delete' })),
  ];
  for (const target of targets) {
    target.segments = splitPortable(target.path);
    if (target.segments === null) {
      throw fail('ERR_INVALID_PATH', `Invalid manifest path: ${JSON.stringify(target.path)}`);
    }
  }

  const seen = new Set();
  for (const target of targets) {
    if (seen.has(target.path)) throw invalid(`Duplicate target: ${target.path}`);
    seen.add(target.path);
  }
  for (const target of targets) {
    for (let depth = 1; depth < target.segments.length; depth++) {
      const ancestor = target.segments.slice(0, depth).join('/');
      if (seen.has(ancestor)) throw invalid(`Target ${ancestor} is an ancestor of ${target.path}`);
    }
  }

  return { writes, deletes, targets };
}

function parseGrants(grants) {
  const invalid = message => fail('ERR_INVALID_GRANT', message);
  if (!Array.isArray(grants)) throw invalid('Grants must be an array');
  const approved = new Set();
  for (let i = 0; i < grants.length; i++) {
    const grant = grants[i];
    if (!isPlainObject(grant) || !hasExactKeys(grant, ['path', 'operation'])) {
      throw invalid(`Grant ${i} must contain exactly path and operation`);
    }
    const { path: relative, operation } = grant;
    if (typeof operation !== 'string' || !OPERATIONS.has(operation)) {
      throw invalid(`Grant ${i} has invalid operation`);
    }
    if (splitPortable(relative) === null) throw invalid(`Grant ${i} has invalid path`);
    approved.add(`${operation}\0${relative}`);
  }
  return approved;
}

async function lstatOrNull(location) {
  try {
    return await fs.lstat(location);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

async function checkTarget(root, target) {
  const unsafe = message => fail('ERR_UNSAFE_TARGET', `${message}: ${target.path}`);
  let current = root;
  for (let i = 0; i < target.segments.length; i++) {
    current = path.join(current, target.segments[i]);
    const stats = await lstatOrNull(current);
    if (stats === null) return; // Nothing below a missing component can exist.
    if (stats.isSymbolicLink()) throw unsafe('Symbolic link in target path');
    const isLast = i === target.segments.length - 1;
    if (!isLast && !stats.isDirectory()) throw unsafe('Target ancestor is not a directory');
    if (isLast && !stats.isFile()) throw unsafe('Target is not a regular file');
  }
}

export async function restore(directory, manifest, grants) {
  const { writes, deletes, targets } = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const target of targets) {
    if (!approved.has(`${target.operation}\0${target.path}`)) {
      throw fail('ERR_DENIED', `${target.operation} not approved: ${target.path}`);
    }
  }

  const root = path.resolve(directory);
  const rootStats = await fs.lstat(root);
  if (rootStats.isSymbolicLink()) throw fail('ERR_UNSAFE_TARGET', 'Root is a symbolic link');
  if (!rootStats.isDirectory()) throw fail('ERR_UNSAFE_TARGET', 'Root is not a directory');
  for (const target of targets) await checkTarget(root, target);

  const resolve = relative => path.join(root, ...relative.split('/'));
  const written = [];
  for (const item of writes) {
    const location = resolve(item.path);
    await fs.mkdir(path.dirname(location), { recursive: true });
    await fs.writeFile(location, item.content, 'utf8');
    written.push(item.path);
  }

  const deleted = [];
  for (const relative of deletes) {
    try {
      await fs.unlink(resolve(relative));
      deleted.push(relative);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
  }
  return { written, deleted };
}

