  try { const r = await fn(); results.push(`${code ? 'FAIL' : 'ok  '} ${name} -> ${JSON.stringify(r)}`); }
  catch (e) { results.push(`${e.code === code ? 'ok  ' : 'FAIL'} ${name} -> ${e.code}`); }
}
